declare const brand: unique symbol;
type PaymentId = string & { readonly [brand]: "PaymentId" };
type Result<T, E> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: E };

function parsePaymentId(raw: string): Result<PaymentId, string> {
  const value = raw.trim().toUpperCase();
  if (!/^PAY-\d{1,12}$/.test(value)) return { ok: false, error: `not a payment id: ${JSON.stringify(raw.trim())}` };
  return { ok: true, value: value as PaymentId };
}

const show = (r: Result<PaymentId, string>): string => (r.ok ? r.value : r.error);
console.log([" pay-88 ", "ORD-7", "PAY-"].map(parsePaymentId).map(show).join(" | "));

