declare const brand: unique symbol;
type Kobo = number & { readonly [brand]: "Kobo" };

function formatKobo(amount: Kobo): string {
  const sign = amount < 0 ? "-" : "";
  const [whole = "0", fraction = "00"] = (Math.abs(amount) / 100).toFixed(2).split(".");
  return `${sign}₦${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${fraction}`;
}

console.log(formatKobo(2138750 as Kobo), formatKobo(-2500 as Kobo), formatKobo(5 as Kobo));

