declare const brand: unique symbol;
type Sku = string & { readonly [brand]: "Sku" };

function parseSkus(raws: readonly string[]): { readonly skus: readonly Sku[]; readonly bad: readonly string[] } {
  const skus = new Set<Sku>();
  const bad: string[] = [];
  for (const raw of raws) {
    const value = raw.trim().toUpperCase();
    if (/^[A-Z]{2,8}-\d{1,4}$/.test(value)) skus.add(value as Sku);
    else bad.push(raw.trim());
  }
  return { skus: [...skus], bad };
}

const { skus, bad } = parseSkus(["rice-5", " OIL-1", "RICE-5", "tv", "SALT"]);
console.log(`${skus.join(",")} | bad: ${bad.join(", ")}`);
